import React, { useState, useEffect } from "react";
import {
    Container,
    Row,
    Col,
    Card,
    Nav,
    Table,
    Button,
    Form,
    InputGroup,
    Alert,
    Spinner
} from "react-bootstrap";
import axios from "axios";

const ADMIN = () => {
    const [activeTab, setActiveTab] = useState("lecturers");
    const [lecturers, setLecturers] = useState([]);
    const [students, setStudents] = useState([]);
    const [courses, setCourses] = useState([]);
    const [modules, setModules] = useState([]);
    const [search, setSearch] = useState("");
    const [loading, setLoading] = useState({ students: false, lecturers: false });
    const [error, setError] = useState("");

    useEffect(() => {
        getStudentData();
        getLecturerData();
    }, []);

    const getStudentData = async () => {
        try {
            setLoading(prev => ({ ...prev, students: true }));
            setError("");
            const result = await axios.get("https://localhost:7281/api/Student/GetStudents");
            setStudents(result.data || []);
        } catch (error) {
            console.error("Error fetching students:", error);
            setError("Failed to load students. Please check if the server is running.");
        } finally {
            setLoading(prev => ({ ...prev, students: false }));
        }
    };

    const getLecturerData = async () => {
        try {
            setLoading(prev => ({ ...prev, lecturers: true }));
            setError("");
            const result = await axios.get("https://localhost:7281/api/Lecturer/GetAllLecturers");
            setLecturers(result.data || []);
        } catch (error) {
            console.error("Error fetching lecturers:", error);
            setError("Failed to load lecturers. Please check if the server is running.");
        } finally {
            setLoading(prev => ({ ...prev, lecturers: false }));
        }
    };

    // Simple logout without navigation
    const handleLogout = () => {
        localStorage.clear();
        sessionStorage.clear();
        // Reload the page or show login form
        window.location.reload();
        // Or if you have a login state management:
        // setUser(null);
    };

    // Alternative: Show/hide login form
    const handleLogoutAlternative = () => {
        localStorage.clear();
        sessionStorage.clear();
        alert("Logged out successfully! Redirecting to login...");
        // You can implement your own login state management here
    };

    const handleAddLecturer = () => {
        alert("Lecturer added ✅");
    };

    const handleAddStudent = () => {
        alert("Student added ✅");
    };

    const handleAddCourse = () => {
        alert("Course added ✅");
    };

    const handleAddModule = () => {
        alert("Module added ✅");
    };

    const handleEdit = (id, type) => {
        alert("Module edited");
    };

    const handleDelete = (id, type) => {
        alert("Module deleted");
    };

    // Filter functions
    const filteredLecturers = lecturers.filter(lecturer =>
        lecturer.name?.toLowerCase().includes(search.toLowerCase()) ||
        lecturer.surname?.toLowerCase().includes(search.toLowerCase())
    );

    const filteredStudents = students.filter(student =>
        student.name?.toLowerCase().includes(search.toLowerCase()) ||
        student.surname?.toLowerCase().includes(search.toLowerCase())
    );

    return (
        <Container fluid className="p-4">
            {/* Main Heading */}
            <Row className="mb-4">
                <Col>
                    <h1 className="text-center fw-bold display-4 text-primary">
                        Educore Learning Management System
                    </h1>
                </Col>
            </Row>

            {/* Logout Button */}
            <Row className="mb-3">
                <Col className="text-end">
                    <Button variant="outline-danger" size="sm" onClick={handleLogout}>
                        Logout
                    </Button>
                </Col>
            </Row>

            {/* Error Alert */}
            {error && (
                <Alert variant="danger" className="mb-3">
                    {error}
                </Alert>
            )}

            <Row>
                <Col>
                    <Card className="shadow">
                        <Card.Header>
                            <h3>Administrator Dashboard</h3>
                        </Card.Header>
                        <Card.Body>
                            <Nav variant="tabs" activeKey={activeTab} onSelect={(k) => setActiveTab(k)}>
                                <Nav.Item><Nav.Link eventKey="lecturers">Lecturers</Nav.Link></Nav.Item>
                                <Nav.Item><Nav.Link eventKey="students">Students</Nav.Link></Nav.Item>
                                <Nav.Item><Nav.Link eventKey="courses">Courses</Nav.Link></Nav.Item>
                                <Nav.Item><Nav.Link eventKey="modules">Modules</Nav.Link></Nav.Item>
                                <Nav.Item><Nav.Link eventKey="assign">Assignments</Nav.Link></Nav.Item>
                            </Nav>

                            <div className="mt-4">
                                {/* Lecturers Tab */}
                                {activeTab === "lecturers" && (
                                    <>
                                        <h4>Manage Lecturers</h4>
                                        <InputGroup className="mb-3">
                                            <Form.Control
                                                placeholder="Search by name or surname"
                                                value={search}
                                                onChange={(e) => setSearch(e.target.value)}
                                            />
                                            <Button variant="primary">Search</Button>
                                        </InputGroup>

                                        <Form className="mb-3">
                                            <Row>
                                                <Col><Form.Control placeholder="Staff Number" /></Col>
                                                <Col><Form.Control placeholder="Name" /></Col>
                                                <Col><Form.Control placeholder="Surname" /></Col>
                                                <Col><Button onClick={handleAddLecturer}>Add</Button></Col>
                                            </Row>
                                        </Form>

                                        <Table striped bordered hover>
                                            <thead>
                                                <tr>
                                                    <th>#</th><th>First Name</th><th>Last Name</th>
                                                    <th>Date Of Birth</th><th>Home Address</th>
                                                    <th>Phone Number</th><th>Actions</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                {loading.lecturers ? (
                                                    <tr><td colSpan="7" className="text-center"><Spinner animation="border" /> Loading...</td></tr>
                                                ) : filteredLecturers.length > 0 ? (
                                                    filteredLecturers.map((item, index) => (
                                                        <tr key={index}>
                                                            <td>{index + 1}</td>
                                                            <td>{item.name || 'N/A'}</td>
                                                            <td>{item.surname || 'N/A'}</td>
                                                            <td>{item.dateOfBirth ? new Date(item.dateOfBirth).toLocaleDateString() : 'N/A'}</td>
                                                            <td>{item.homeAddress || 'N/A'}</td>
                                                            <td>{item.phoneNumber || 'N/A'}</td>
                                                            <td>
                                                                <Button size="sm" variant="primary" 
                                                                    onClick={() => handleEdit(item.lecturerId || item.id, 'lecturer')}>
                                                                    Edit
                                                                </Button>{' '}
                                                                <Button size="sm" variant="danger"
                                                                    onClick={() => handleDelete(item.lecturerId || item.id, 'lecturer')}>
                                                                    Delete
                                                                </Button>
                                                            </td>
                                                        </tr>
                                                    ))
                                                ) : (
                                                    <tr><td colSpan="7" className="text-center">No lecturers found</td></tr>
                                                )}
                                            </tbody>
                                        </Table>
                                    </>
                                )}

                                {/* Students Tab */}
                                {activeTab === "students" && (
                                    <>
                                        <h4>Manage Students</h4>
                                        <InputGroup className="mb-3">
                                            <Form.Control
                                                placeholder="Search by name or surname"
                                                value={search}
                                                onChange={(e) => setSearch(e.target.value)}
                                            />
                                            <Button variant="primary">Search</Button>
                                        </InputGroup>

                                        <Form className="mb-3">
                                            <Row>
                                                <Col><Form.Control placeholder="Student Number" /></Col>
                                                <Col><Form.Control placeholder="Name" /></Col>
                                                <Col><Form.Control placeholder="Surname" /></Col>
                                                <Col><Button onClick={handleAddStudent}>Add</Button></Col>
                                            </Row>
                                        </Form>

                                        <Table striped bordered hover>
                                            <thead>
                                                <tr>
                                                    <th>#</th><th>First Name</th><th>Last Name</th>
                                                    <th>Date Of Birth</th><th>Home Address</th>
                                                    <th>Phone Number</th><th>Actions</th>
                                                </tr>
                                            </thead>
                                            <tbody>
                                                {loading.students ? (
                                                    <tr><td colSpan="7" className="text-center"><Spinner animation="border" /> Loading...</td></tr>
                                                ) : filteredStudents.length > 0 ? (
                                                    filteredStudents.map((item, index) => (
                                                        <tr key={index}>
                                                            <td>{index + 1}</td>
                                                            <td>{item.name || 'N/A'}</td>
                                                            <td>{item.surname || 'N/A'}</td>
                                                            <td>{item.dateOfBirth ? new Date(item.dateOfBirth).toLocaleDateString() : 'N/A'}</td>
                                                            <td>{item.homeAddress || 'N/A'}</td>
                                                            <td>{item.phoneNumber || 'N/A'}</td>
                                                            <td>
                                                                <Button size="sm" variant="primary"
                                                                    onClick={() => handleEdit(item.studentId || item.id, 'student')}>
                                                                    Edit
                                                                </Button>{' '}
                                                                <Button size="sm" variant="danger"
                                                                    onClick={() => handleDelete(item.studentId || item.id, 'student')}>
                                                                    Delete
                                                                </Button>
                                                            </td>
                                                        </tr>
                                                    ))
                                                ) : (
                                                    <tr><td colSpan="7" className="text-center">No students found</td></tr>
                                                )}
                                            </tbody>
                                        </Table>
                                    </>
                                )}

                                {/* Other tabs */}
                                {activeTab === "courses" && (
                                    <div className="text-center p-4">
                                        <h4>Courses Management</h4>
                                        <p>Courses functionality coming soon...</p>
                                    </div>
                                )}

                                {activeTab === "modules" && (
                                    <div className="text-center p-4">
                                        <h4>Modules Management</h4>
                                        <p>Modules functionality coming soon...</p>
                                    </div>
                                )}

                                {activeTab === "assign" && (
                                    <div className="text-center p-4">
                                        <h4>Assignments Management</h4>
                                        <p>Assignments functionality coming soon...</p>
                                    </div>
                                )}
                            </div>
                        </Card.Body>
                    </Card>
                </Col>
            </Row>
        </Container>
    );
};

export default ADMIN;
